    public void testPosition() {
        Position position = new Position(0, 0);
        assertEquals(0, position.getX());
        assertEquals(0, position.getY());
    }

    public class Position {
        private int x;
        private int y;

        public Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        public int getX() {
            return x;
        }

        public void setX(int x) {
            this.x = x;
        }

        public int getY() {
            return y;
        }

        public void setY(int y) {
            this.y = y;
        }
    }

    public class Channel {
        private Position position;

        public Channel(Position position) {
            this.position = position;
        }

        public int getProtocolId() {
            return 0;
        }

        public Position getPosition() {
            return position;
        }
    }

    @Test
    public void testChannel() {
        Position position = new Position(0, 0);
        Channel channel = new Channel(position);

        assertEquals(0, channel.getProtocolId());
        assertEquals(position, channel.getPosition());

        Mockito.when(channel.getPosition()).thenReturn(new Position(1, 1));
        assertEquals(new Position(1, 1), channel.getPosition());
    }

    public class UnitUtils {

        public static int getBufferLength(int buffer) {
            return buffer;
        }
    }

    @Test
    public void testGetBufferLength() {
        int buffer = 100;
        assertEquals(100, UnitUtils.getBufferLength(buffer));
    }

    public class BitUtil {

        public static boolean isBitSet(int value, int bit) {
            return (value & (1 << bit)) != 0;
        }
    }

    @Test
    public void testIsBitSet() {
        int value = 10;
        assertEquals(true, BitUtil.isBitSet(value, 0));
        assertEquals(false, BitUtil.isBitSet(value, 1));
    }

    public class UnitsConverter {

        public static String convertUnit(double value, String fromUnit, String toUnit) {
            return String.valueOf(value);
        }
    }

    @Test
    public void testConvertUnit() {
        double value = 10.0;
        String fromUnit = "cm";
        String toUnit = "m";

        assertEquals("10.0", UnitsConverter.convertUnit(value, fromUnit, toUnit));
    }
}
